/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field PriceDate.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModulePriceDate extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, PriceDate);
}

public Set getAllowedValues()
{
    InventTableModule   inventTableModule;
    var                 ret = new Set(Types::Date);

    while select PriceDate from inventTableModule
        group by PriceDate
    {
        if (!ret.in(inventTableModule.PriceDate))
        {
            ret.add(inventTableModule.PriceDate);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, PriceDate));
    qbr.value(queryValue(_value));
}
